/**
 * @brief Announce the flight modes of an autopilot, the counterpart of the Modes plugin.
 *
 * The modes are announced using the MAVLink standard modes protocol
 * (AVAILABLE_MODES, AVAILABLE_MODES_MONITOR, CURRENT_MODE). The current mode
 * is the custom mode of the server component.
 *
 * This plugin doesn't change modes itself: MAV_CMD_DO_SET_STANDARD_MODE is
 * answered as unsupported, so clients fall back to MAV_CMD_DO_SET_MODE, which
 * the ActionServer plugin handles.
 */

// ===== Forward Declarations =====
typedef struct mavsdk_server_component_s *mavsdk_server_component_t;

// ===== Opaque Handles =====
typedef struct mavsdk_modes_server_s *mavsdk_modes_server_t;

// ===== Enums =====

// ===== Structs =====
/**
 * @brief Mode type.
 *
 * @note This struct may contain dynamically allocated memory. Always call
 *       mavsdk_modes_server_mode_destroy() when done to avoid memory leaks.
 */
typedef struct CMAVSDK_EXPORT {
    /**  Name of the mode, for a standard mode one of the standard names, e.g. "Position" or "Mission" */
    char* name;
    /**  Autopilot specific custom mode, needs to be unique */
    uint32_t custom_mode;
    /**  True if this is a MAVLink standard mode */
    bool is_standard;
    /**  True if the mode can be set by the user */
    bool is_user_selectable;
    /**  True if the mode is for advanced users only */
    bool is_advanced;
    /**  True if the mode runs autonomously, e.g. Mission or Land */
    bool is_auto_mode;
} mavsdk_modes_server_mode_t;

